def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = sum(1 for a in opp if a == 'D')
    me_d = sum(1 for a in me if a == 'D')
    last_me, last_opp = history[-1]

    if n >= 97:
        return 'D'

    recent_len = min(10, n)
    recent = opp[-recent_len:]
    recent_d = sum(1 for a in recent if a == 'D')

    if opp_d == 0:
        if n >= 90:
            return 'D' if rng.random() < 0.6 else 'C'
        if n >= 40 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if opp_d * 5 >= n * 4:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    if recent_len >= 4 and recent_d * 2 >= recent_len:
        if opp[-1] == 'C' and rng.random() < 0.3:
            return 'C'
        return 'D'

    if last_opp == 'D':
        consec = 0
        for a in reversed(opp):
            if a == 'D':
                consec += 1
            else:
                break
        if consec == 1 and opp_d * 3 < n:
            return 'D' if rng.random() < 0.5 else 'C'
        if consec >= 2:
            if opp_d * 3 > n:
                return 'D'
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        return 'D'

    if opp_d * 4 < n:
        my_consec_c = 0
        for a in reversed(me):
            if a == 'C':
                my_consec_c += 1
            else:
                break
        if my_consec_c >= 4 and rng.random() < 0.07:
            return 'D'
        return 'C'

    if opp_d * 2 < n:
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    if last_me == 'D' and last_opp == 'C':
        return 'C'

    return 'C'
